  OR login_deadline>=s.valid_until OR login_deadline>=l.valid_until OR observed_now<l.granted_at THEN
  RAISE EXCEPTION 'Twenty-minute login must lie strictly within current scope and named permit'; END IF;
 EXECUTE format('ALTER ROLE %I LOGIN VALID UNTIL %L','monaco_ledger_runner',login_deadline);
END $v2_login$;
